import {Pool} from '/Users/citrine/Projects/AgentHarness/Flow/node_modules/pg/lib/index.js';
import {loadPreviewConfiguration} from '/Users/citrine/Projects/AgentHarness/Flow/tools/personal-preview/preview.mjs';
import {durable} from '/Users/citrine/Projects/AgentHarness/Flow-worktrees/personal-history-compatibility/docs/evidence/svc05-history-compatibility/center-recovery-af51/facts.mjs';
import assert from 'node:assert/strict';
const config=await loadPreviewConfiguration('/Users/citrine/.flow-personal');const pool=new Pool({connectionString:config.databaseUrl,max:1,connectionTimeoutMillis:1500,statement_timeout:3000,query_timeout:4000,application_name:'svc06-personal-history-readonly'});
const result={at:new Date().toISOString(),tables:[]};
try{const c=await pool.connect();try{await c.query('BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY');
 const tables=(await c.query("SELECT tablename FROM pg_tables WHERE schemaname='flow' ORDER BY tablename LIMIT 101")).rows;assert.ok(tables.length<=100);
 for(const {tablename:name} of tables){assert.match(name,/^[a-z_]+$/);const names=(await c.query("SELECT column_name FROM information_schema.columns WHERE table_schema='flow' AND table_name=$1 ORDER BY ordinal_position",[name])).rows.map(x=>x.column_name);assert.ok(names.length>0&&names.length<100&&names.every(n=>/^[a-z_]+$/.test(n)));
 const columns=names.filter(n=>!(name==='conversations'&&n==='queue_checked_at'));
 const d=(await c.query(`SELECT count(*)::int AS count,md5(coalesce(string_agg(h,'' ORDER BY h),'')) AS digest FROM (SELECT md5(to_jsonb(x)::text) AS h FROM (SELECT ${columns.map(n=>'"'+n+'"').join(',')} FROM flow."${name}" LIMIT 10001)x)y`)).rows[0];assert.ok(d.count<=10000);result.tables.push({name,columns,...d});
 }await c.query('COMMIT');}finally{c.release();}}finally{await pool.end();}
await durable(process.argv[1]+'/history-before.json',result);console.log(JSON.stringify({outcome:'observed',tables:result.tables.length}));
